CREATE OR REPLACE FUNCTION calculate_market_risk(dlyflow_in bigint, esccomprate_in numeric, interscore_in numeric, vendcount_in integer, mktspan_in integer) RETURNS numeric AS $$
SELECT ROUND(CAST($1 / 1000.0 + ($2 * 0.2) + ($3 * 0.3) + ($4 * 0.1) - $5 / 100.0 AS numeric), 4);
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION calculate_market_risk(dlyflow_in bigint, esccomprate_in numeric, interscore_in numeric, vendcount_in integer, mktspan_in integer) RETURNS TABLE(market_risk_score numeric) AS $$
BEGIN
    RETURN QUERY SELECT ROUND(CAST(dlyflow_in / 1000.0 + (esccomprate_in * 0.2) + (interscore_in * 0.3) + (vendcount_in * 0.1) - mktspan_in / 100.0 AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk() RETURNS SETOF numeric AS $$
    SELECT ROUND(CAST(dlyflow / 1000.0 + (esccomprate * 0.2) + (interscore * 0.3) + (vendcount * 0.1) - mktspan / 100.0 AS numeric), 4) FROM markets;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION calculate_market_risk() RETURNS TABLE(market_risk_score numeric) AS $$
    SELECT ROUND(CAST(dlyflow / 1000.0 + (esccomprate * 0.2) + (interscore * 0.3) + (vendcount * 0.1) - mktspan / 100.0 AS numeric), 4) FROM markets;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION calculate_market_risk() RETURNS TABLE(market_risk_score numeric) AS $$
    SELECT (dlyflow / 1000.0 + (esccomprate * 0.2) + (interscore * 0.3) + (vendcount * 0.1) - mktspan / 100.0)::numeric FROM markets;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION calculate_market_risk(p_mktreg character varying) RETURNS numeric AS $$
DECLARE result numeric;
BEGIN
    SELECT INTO result ROUND(CAST(dlyflow / 1000.0 + (esccomprate * 0.2) + (interscore * 0.3) + (vendcount * 0.1) - mktspan / 100.0 AS numeric), 4) FROM markets WHERE mktregistry = p_mktreg;
    RETURN result;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(flow numeric, rate numeric, score numeric, count integer, lifespan integer) RETURNS numeric AS $$
BEGIN
    RETURN ROUND(CAST(flow / 1000.0 + (rate * 0.2) + (score * 0.3) + (count * 0.1) - lifespan / 100.0 AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_market_risk(flow numeric, rate numeric, score numeric, count integer, lifespan integer) RETURNS TABLE(market_risk_score numeric) AS $$
    SELECT ROUND(CAST(flow / 1000.0 + (rate * 0.2) + (score * 0.3) + (count * 0.1) - lifespan / 100.0 AS numeric), 4);
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION calculate_market_risk(p_flow numeric, p_rates numeric, p_scores numeric, p_counts integer, p_lifespan integer) RETURNS TABLE(market_risk_score numeric) AS $$
    SELECT ROUND(CAST(p_flow / 1000.0 + (p_rates * 0.2) + (p_scores * 0.3) + (p_counts * 0.1) - p_lifespan / 100.0 AS numeric), 4);
$$ LANGUAGE sql;

